#max tokens and finish reason
import os
from dotenv import load_dotenv
load_dotenv()
from groq import Groq
client = Groq(api_key=os.getenv("GROQ_API_KEY")) 
prompt = [{"role": "user", "content": "Write a one-sentence apology to a customer whose parcel is late."}]
#in maximum 100 tokens will be generated by the model
response = client.chat.completions.create(
        model="openai/gpt-oss-120b", messages=prompt, max_completion_tokens=100,reasoning_effort = 'low'
    )
choice = response.choices[0]
content = choice.message.content
reasoning = choice.message.reasoning #we are accessing the reason of the model's response
print(f'The model generated the following content: {content}')
#here finish reason represents whether the model has completed its response or its response was cutoff at the maximum token limit 
print(f'The finish reason for the completion is: {choice.finish_reason}')
print(f'The completion token is: {response.usage.completion_tokens}')  #number of tokens used for the completion of response
print(f'The reasoning token is: {response.usage.completion_tokens_details.reasoning_tokens}')  #number of tokens used for reasoning 